values
('1', '5-marla-modern-house-dha-phase-6', '5 Marla Modern House in DHA Phase 6', 'A beautifully designed modern home with a spacious lounge, open kitchen and a terrace. Located in a secure block close to parks and schools.', 32500000, 'sale', 'house', 'Lahore', 'DHA Phase 6', 'Block K, DHA Phase 6, Lahore', 3, 4, 5, 'marla', ARRAY['/images/properties/dha-house-1.jpg', '/images/properties/dha-house-2.jpg', '/images/properties/dha-house-3.jpg']::text[], ARRAY['Parking', 'Gas', 'Security', 'Terrace', 'Near Park']::text[], true, 'agent-1', 31.4697, 74.4015),
('2', '1-kanal-luxury-villa-gulberg', '1 Kanal Luxury Villa in Gulberg', 'A grand villa with a double-height lounge, home theater, servant quarters and a landscaped lawn in the heart of Gulberg.', 145000000, 'sale', 'house', 'Lahore', 'Gulberg', 'Gulberg III, Lahore', 5, 6, 1, 'kanal', ARRAY['/images/properties/gulberg-villa-1.jpg', '/images/properties/gulberg-villa-2.jpg', '/images/properties/gulberg-villa-3.jpg']::text[], ARRAY['Lawn', 'Home Theater', 'Servant Quarter', 'Parking', 'Security']::text[], true, 'agent-1', 31.5204, 74.3587),
('3', '2-bed-apartment-for-rent-johar-town', '2 Bed Apartment for Rent in Johar Town', 'A bright, well-maintained apartment on the 3rd floor with a lift, backup power and a quiet neighborhood.', 85000, 'rent', 'apartment', 'Lahore', 'Johar Town', 'Block R1, Johar Town, Lahore', 2, 2, 1100, 'sqft', ARRAY['/images/properties/appartment-1.jpg', '/images/properties/appartment-2.jpg']::text[], ARRAY['Lift', 'Backup Power', 'Parking', 'Gas']::text[], false, 'agent-2', 31.4697, 74.2728),
('4', '10-marla-plot-bahria-town', '10 Marla Residential Plot in Bahria Town', 'A corner plot on a 60 ft road, ready for construction. All utilities available and close to the main boulevard.', 14500000, 'sale', 'plot', 'Lahore', 'Bahria Town', 'Sector C, Bahria Town, Lahore', NULL, NULL, 10, 'marla', ARRAY['/images/properties/plot-1.jpg', '/images/properties/plot-2.jpg']::text[], ARRAY['Corner', 'Near Park', 'Possession Ready']::text[], true, 'agent-2', 31.365, 74.18),
('5', 'commercial-shop-for-sale-mall-road', 'Commercial Shop on Mall Road', 'A ground-floor shop in a high-traffic area, ideal for retail or a showroom. Strong rental income potential.', 48000000, 'sale', 'commercial', 'Lahore', 'Mall Road', 'Mall Road, Lahore', NULL, NULL, 600, 'sqft', ARRAY['/images/properties/shop-1.jpg', '/images/properties/shop-2.jpg']::text[], ARRAY['Main Road', 'Ground Floor', 'Rental Income']::text[], false, 'agent-1', 31.5546, 74.3436),
('6', '7-marla-house-for-rent-model-town', '7 Marla House for Rent in Model Town', 'A clean family home with a lawn, separate drawing room and ample parking, near markets and schools.', 180000, 'rent', 'house', 'Lahore', 'Model Town', 'Block C, Model Town, Lahore', 4, 3, 7, 'marla', ARRAY['/images/properties/garden.jpg']::text[], ARRAY['Lawn', 'Parking', 'Gas', 'Near Market']::text[], true, 'agent-2', 31.483, 74.325);
